// Simulated Mongoose Model for CRUD
const User = {
  create: async (data) => console.log(`[CREATE]: Inserted ${data.name} into DB`),
  find: async () => console.log(`[READ]: Retrieved all users from DB`),
  findByIdAndUpdate: async (id, data) => console.log(`[UPDATE]: Changed user ${id} name to ${data.name}`),
  findByIdAndDelete: async (id) => console.log(`[DELETE]: User ${id} removed from DB`)
};

async function runCrud() {
  // 1. Create (POST)
  await User.create({ name: "Alice" });

  // 2. Read (GET)
  await User.find();

  // 3. Update (PUT/PATCH)
  await User.findByIdAndUpdate(1, { name: "Alicia" });

  // 4. Delete (DELETE)
  await User.findByIdAndDelete(1);
}

runCrud();
